public class LengthSorterCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(LengthSorter impl) {
        try {
            return LengthSorterChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectSorter()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectSorter()));
        check("rejects the missing alphabetical tie-break", false, verdict(new NoTieBreakSorter()));
        check("rejects the version that sorts the caller's list", false, verdict(new InPlaceSorter()));
        check("rejects the ordering that runs longest to shortest", false, verdict(new LongestFirstSorter()));
        check("rejects the version that ignores length entirely", false, verdict(new AlphabeticalSorter()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectSorter implements LengthSorter {
    public java.util.List<String> sorted(java.util.List<String> words) {
        java.util.List<String> copy = new java.util.ArrayList<>(words);
        copy.sort(java.util.Comparator.comparingInt(String::length)
                .thenComparing(java.util.Comparator.naturalOrder()));
        return copy;
    }
}

class AlsoCorrectSorter implements LengthSorter {
    public java.util.List<String> sorted(java.util.List<String> words) {
        java.util.List<String> copy = new java.util.ArrayList<>(words);
        copy.sort((a, b) -> a.length() != b.length()
                ? Integer.compare(a.length(), b.length())
                : a.compareTo(b));
        return copy;
    }
}

class NoTieBreakSorter implements LengthSorter {
    public java.util.List<String> sorted(java.util.List<String> words) {
        java.util.List<String> copy = new java.util.ArrayList<>(words);
        copy.sort(java.util.Comparator.comparingInt(String::length));
        return copy;
    }
}

class InPlaceSorter implements LengthSorter {
    public java.util.List<String> sorted(java.util.List<String> words) {
        words.sort(java.util.Comparator.comparingInt(String::length)
                .thenComparing(java.util.Comparator.naturalOrder()));
        return words;
    }
}

class LongestFirstSorter implements LengthSorter {
    public java.util.List<String> sorted(java.util.List<String> words) {
        java.util.List<String> copy = new java.util.ArrayList<>(words);
        copy.sort(java.util.Comparator.comparingInt(String::length).reversed()
                .thenComparing(java.util.Comparator.naturalOrder()));
        return copy;
    }
}

class AlphabeticalSorter implements LengthSorter {
    public java.util.List<String> sorted(java.util.List<String> words) {
        java.util.List<String> copy = new java.util.ArrayList<>(words);
        java.util.Collections.sort(copy);
        return copy;
    }
}

