/**
 * TASK: Write the checks that decide whether a LengthSorter is correct.
 *
 *   sorted(words) returns a NEW list ordered by length, shortest first.
 *   Words of equal length are ordered alphabetically among themselves.
 *   The list passed in must not be modified. An empty list gives an empty list.
 *   Example: sorted(["pear", "fig", "kiwi", "date"]) -> [fig, date, kiwi, pear]
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a value, so a crash counts as a failure: wrap your calls
 * in try/catch and return false if anything is thrown.
 *
 * One happy-path call is not a test suite. Choose inputs that expose specific
 * bugs, including the boundary cases named in the contract.
 */
import java.util.List;

interface LengthSorter {
    /* Provided -- do not edit. */
    List<String> sorted(List<String> words);
}

public class LengthSorterChecker {

    public static boolean isCorrect(LengthSorter impl) {
        try {
            java.util.List<String> input =
                    new java.util.ArrayList<>(java.util.List.of("pear", "fig", "kiwi", "date"));
            java.util.List<String> result = impl.sorted(input);
            if (!java.util.List.of("fig", "date", "kiwi", "pear").equals(result)) return false;
            if (!java.util.List.of("pear", "fig", "kiwi", "date").equals(input)) return false;

            if (!java.util.List.of().equals(impl.sorted(java.util.List.of()))) return false;
            if (!java.util.List.of("a").equals(impl.sorted(java.util.List.of("a")))) return false;
            if (!java.util.List.of("ant", "bee", "cow").equals(
                    impl.sorted(java.util.List.of("cow", "ant", "bee")))) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
